public static int nextPrime(int n) {
    int candidate = n + 1;
    while (!isPrime(candidate)) {
        candidate++;
    }
    return candidate;
}

private static boolean isPrime(int num) {
    if (num < 2) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;
    int i = 3;
    while (i * i <= num) {
        if (num % i == 0) return false;
        i += 2;
    }
    return true;
}
// The outer while loop continues until a prime is found.
// The inner while loop (i*i <= num) is the efficient O(√n) primality test.

